// SUNSET срез 5. Запуск: node setup5.mjs
import { mkdirSync, writeFileSync, existsSync } from 'node:fs'
import { dirname } from 'node:path'
if (!existsSync('package.json') || !existsSync('src')) {
  console.error('ОШИБКА: запусти этот файл внутри папки sunset-app (где лежит package.json).')
  process.exit(1)
}
const files = {
 "supabase/migrations/0004_slice5.sql": "-- SUNSET slice 5: pins, forwarded label, wallets + market (Stars). Run in Supabase SQL Editor.\n\n-- ===== messages / pins =====\nalter table public.messages add column if not exists forwarded_from text check (char_length(forwarded_from) <= 100);\n\ncreate table public.chat_pins (\n  chat_id    uuid primary key references public.chats(id) on delete cascade,\n  message_id uuid not null references public.messages(id) on delete cascade,\n  pinned_by  uuid not null references public.profiles(id),\n  created_at timestamptz not null default now()\n);\nalter table public.chat_pins enable row level security;\ncreate policy pins_select on public.chat_pins for select to authenticated using (public.is_chat_member(chat_id));\ncreate policy pins_insert on public.chat_pins for insert to authenticated\n  with check (public.is_chat_member(chat_id) and pinned_by = auth.uid()\n    and exists (select 1 from public.messages m where m.id = chat_pins.message_id and m.chat_id = chat_pins.chat_id));\ncreate policy pins_update on public.chat_pins for update to authenticated\n  using (public.is_chat_member(chat_id))\n  with check (public.is_chat_member(chat_id) and pinned_by = auth.uid()\n    and exists (select 1 from public.messages m where m.id = chat_pins.message_id and m.chat_id = chat_pins.chat_id));\ncreate policy pins_delete on public.chat_pins for delete to authenticated using (public.is_chat_member(chat_id));\nalter publication supabase_realtime add table public.chat_pins;\n\n-- ===== profile showcase (cosmetic, set only via functions) =====\nalter table public.profiles add column if not exists showcase_number text check (char_length(showcase_number) <= 30);\nalter table public.profiles add column if not exists showcase_handle text check (char_length(showcase_handle) <= 30);\n\n-- ===== wallets & market =====\ncreate table public.wallets (\n  user_id uuid primary key references public.profiles(id) on delete cascade,\n  stars   bigint not null default 0 check (stars >= 0)\n);\ncreate table public.market_items (\n  id         uuid primary key default gen_random_uuid(),\n  kind       text not null check (kind in ('number', 'username')),\n  value      text not null check (char_length(value) between 2 and 30),\n  owner_id   uuid references public.profiles(id) on delete set null, -- null = платформа\n  price      bigint check (price > 0 and price <= 1000000000),       -- null = не продаётся\n  created_at timestamptz not null default now(),\n  unique (kind, value)\n);\nalter table public.wallets enable row level security;\nalter table public.market_items enable row level security;\ncreate policy wallets_select on public.wallets for select to authenticated using (user_id = auth.uid());\ncreate policy market_select on public.market_items for select to authenticated\n  using (price is not null or owner_id = auth.uid());\n-- no insert/update/delete policies: all writes go through the functions below\n\ncreate function public.my_stars() returns bigint language sql stable security invoker set search_path = '' as $$\n  select coalesce((select stars from public.wallets where user_id = auth.uid()), 0);\n$$;\n\ncreate function public.market_buy(p_item uuid) returns void\nlanguage plpgsql security definer set search_path = '' as $$\ndeclare v_me uuid := auth.uid(); it public.market_items%rowtype;\nbegin\n  if v_me is null then raise exception 'not authenticated'; end if;\n  select * into it from public.market_items where id = p_item for update;\n  if not found or it.price is null then raise exception 'item not for sale'; end if;\n  if it.owner_id = v_me then raise exception 'already yours'; end if;\n\n  update public.wallets set stars = stars - it.price where user_id = v_me and stars >= it.price;\n  if not found then raise exception 'not enough stars'; end if;\n\n  if it.owner_id is not null then\n    insert into public.wallets as w (user_id, stars) values (it.owner_id, it.price)\n      on conflict (user_id) do update set stars = w.stars + excluded.stars;\n    if it.kind = 'number' then\n      update public.profiles set showcase_number = null where id = it.owner_id and showcase_number = it.value;\n    else\n      update public.profiles set showcase_handle = null where id = it.owner_id and showcase_handle = it.value;\n    end if;\n  end if;\n  update public.market_items set owner_id = v_me, price = null where id = p_item;\nend $$;\n\ncreate function public.market_list(p_item uuid, p_price bigint) returns void\nlanguage plpgsql security definer set search_path = '' as $$\ndeclare v_me uuid := auth.uid(); it public.market_items%rowtype;\nbegin\n  select * into it from public.market_items where id = p_item and owner_id = v_me for update;\n  if not found then raise exception 'not your item'; end if;\n  if p_price is null or p_price < 1 or p_price > 1000000000 then raise exception 'bad price'; end if;\n  update public.market_items set price = p_price where id = p_item;\n  if it.kind = 'number' then\n    update public.profiles set showcase_number = null where id = v_me and showcase_number = it.value;\n  else\n    update public.profiles set showcase_handle = null where id = v_me and showcase_handle = it.value;\n  end if;\nend $$;\n\ncreate function public.market_unlist(p_item uuid) returns void\nlanguage sql security definer set search_path = '' as $$\n  update public.market_items set price = null where id = p_item and owner_id = auth.uid();\n$$;\n\ncreate function public.market_apply(p_item uuid) returns void\nlanguage plpgsql security definer set search_path = '' as $$\ndeclare v_me uuid := auth.uid(); it public.market_items%rowtype;\nbegin\n  select * into it from public.market_items where id = p_item and owner_id = v_me;\n  if not found then raise exception 'not your item'; end if;\n  if it.price is not null then raise exception 'unlist first'; end if;\n  if it.kind = 'number' then update public.profiles set showcase_number = it.value where id = v_me;\n  else update public.profiles set showcase_handle = it.value where id = v_me; end if;\nend $$;\n\ncreate function public.market_unapply(p_kind text) returns void\nlanguage plpgsql security definer set search_path = '' as $$\nbegin\n  if p_kind = 'number' then update public.profiles set showcase_number = null where id = auth.uid();\n  elsif p_kind = 'username' then update public.profiles set showcase_handle = null where id = auth.uid();\n  end if;\nend $$;\n\n-- admin-only helper: run it yourself in SQL Editor, clients cannot call it\ncreate function public.grant_stars_by_username(p_username text, p_amount bigint) returns void\nlanguage plpgsql security definer set search_path = '' as $$\ndeclare v_id uuid;\nbegin\n  select id into v_id from public.profiles where username = lower(p_username);\n  if v_id is null then raise exception 'user not found'; end if;\n  insert into public.wallets as w (user_id, stars) values (v_id, greatest(p_amount, 0))\n    on conflict (user_id) do update set stars = w.stars + greatest(p_amount, 0);\nend $$;\n\nrevoke all on function public.grant_stars_by_username(text, bigint) from public, anon, authenticated;\nrevoke all on function public.my_stars(), public.market_buy(uuid), public.market_list(uuid, bigint),\n  public.market_unlist(uuid), public.market_apply(uuid), public.market_unapply(text) from public, anon;\ngrant execute on function public.my_stars(), public.market_buy(uuid), public.market_list(uuid, bigint),\n  public.market_unlist(uuid), public.market_apply(uuid), public.market_unapply(text) to authenticated;\n\n-- ===== starter inventory owned by the platform =====\ninsert into public.market_items (kind, value, price)\nselect 'number', '+888 ' || lpad((1000 + n * 137)::text, 4, '0') || ' ' || lpad(((n * 7919) % 10000)::text, 4, '0'), 50 + n * 25\nfrom generate_series(1, 12) as n on conflict (kind, value) do nothing;\n\ninsert into public.market_items (kind, value, price)\nselect 'username', u, greatest(500 - length(u) * 80, 50)\nfrom unnest(array['ace','nova','luna','sol','kai','zen','aura','echo','vega','neo','rex','onyx']) as u\non conflict (kind, value) do nothing;\n\n-- test: give yourself Stars (replace the username):\n-- select public.grant_stars_by_username('gandon', 1000);\n",
 "src/index.css": "@import \"tailwindcss\";\n\n@theme inline {\n  --color-bg: var(--bg);\n  --color-bg2: var(--bg2);\n  --color-surface: var(--surface);\n  --color-line: var(--line);\n  --color-text: var(--text);\n  --color-muted: var(--muted);\n  --color-accent: var(--accent);\n  --color-on-accent: var(--on-accent);\n  --color-pink: var(--danger);\n  --font-sans: \"Inter\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n}\n\n:root, [data-theme=\"dark\"] {\n  color-scheme: dark;\n  --bg: #0b0b10; --bg2: #12121a; --surface: #191923; --line: rgb(255 255 255 / 0.06);\n  --text: #f5f5f7; --muted: #92929f; --accent: #f29abf; --on-accent: #1a0f14; --danger: #ff7a90;\n}\n[data-theme=\"light\"] {\n  color-scheme: light;\n  --bg: #f4f4f7; --bg2: #ffffff; --surface: #ececf1; --line: rgb(0 0 0 / 0.08);\n  --text: #17171c; --muted: #6b6b78; --accent: #d65a8e; --on-accent: #ffffff; --danger: #d6405f;\n}\n\nhtml, body, #root { height: 100%; }\nbody { background: var(--bg); color: var(--text); font-family: var(--font-sans); }\n\n.sunset-gradient { background: var(--accent); }\n.glass { background: var(--bg2); border: 1px solid var(--line); }\n\n[data-motion=\"off\"] *, [data-motion=\"off\"] *::before, [data-motion=\"off\"] *::after {\n  transition: none !important;\n  animation: none !important;\n}\n",
 "src/main.tsx": "import { StrictMode } from 'react'\nimport { createRoot } from 'react-dom/client'\nimport './index.css'\nimport App from './App'\nimport { SessionProvider } from './features/auth/session'\nimport { getFlag, loadTheme } from './lib/prefs'\n\ndocument.documentElement.dataset.theme = loadTheme()\ndocument.documentElement.dataset.motion = getFlag('motion') ? 'on' : 'off'\n\ncreateRoot(document.getElementById('root')!).render(\n  <StrictMode>\n    <SessionProvider>\n      <App />\n    </SessionProvider>\n  </StrictMode>,\n)\n",
 "src/lib/types.ts": "export interface Profile {\n  id: string\n  username: string\n  display_name: string\n  bio: string | null\n  avatar_url: string | null\n  created_at: string\n  showcase_number: string | null\n  showcase_handle: string | null\n}\n\nexport interface Message {\n  id: string\n  chat_id: string\n  sender_id: string\n  body: string | null\n  reply_to: string | null\n  created_at: string\n  edited_at: string | null\n  forwarded_from: string | null\n}\n\nexport interface Reaction {\n  message_id: string\n  user_id: string\n  emoji: string\n}\n\nexport interface LastMessage {\n  body: string | null\n  created_at: string\n  sender_id: string\n}\n\nexport interface ChatItem {\n  id: string\n  kind: 'direct' | 'group' | 'saved'\n  name: string\n  username: string | null\n  avatarUrl: string | null\n  bio: string | null\n  otherId: string | null\n  joinedAt: string | null\n  number: string | null\n  handle: string | null\n}\n\nexport interface MarketItem {\n  id: string\n  kind: 'number' | 'username'\n  value: string\n  owner_id: string | null\n  price: number | null\n}\n",
 "src/lib/prefs.ts": "export type Theme = 'dark' | 'light'\n\nfunction read(key: string): string | null {\n  try { return localStorage.getItem(key) } catch { return null }\n}\nfunction write(key: string, value: string | null): boolean {\n  try {\n    if (value === null) localStorage.removeItem(key)\n    else localStorage.setItem(key, value)\n    return true\n  } catch { return false }\n}\n\nexport const loadTheme = (): Theme => (read('sunset.theme') === 'light' ? 'light' : 'dark')\nexport function saveTheme(theme: Theme) {\n  write('sunset.theme', theme)\n  document.documentElement.dataset.theme = theme\n}\n\nexport const loadBackground = () => read('sunset.bg')\nexport const saveBackground = (value: string | null) => write('sunset.bg', value)\n\nexport function getMuted(): string[] {\n  try {\n    const v: unknown = JSON.parse(read('sunset.muted') ?? '[]')\n    return Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : []\n  } catch { return [] }\n}\nexport const setMuted = (ids: string[]) => { write('sunset.muted', JSON.stringify(ids)) }\n\nlet audio: AudioContext | null = null\nexport function playBeep() {\n  try {\n    audio ??= new AudioContext()\n    void audio.resume()\n    const osc = audio.createOscillator()\n    const gain = audio.createGain()\n    const t = audio.currentTime\n    osc.frequency.value = 880\n    gain.gain.setValueAtTime(0.0001, t)\n    gain.gain.exponentialRampToValueAtTime(0.15, t + 0.01)\n    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.25)\n    osc.connect(gain).connect(audio.destination)\n    osc.start(t)\n    osc.stop(t + 0.26)\n  } catch { /* звук необязателен */ }\n}\n\nexport async function fileToBackground(file: File): Promise<string> {\n  if (!file.type.startsWith('image/')) throw new Error('Нужна картинка.')\n  const bmp = await createImageBitmap(file)\n  const scale = Math.min(1, 1600 / Math.max(bmp.width, bmp.height))\n  const canvas = document.createElement('canvas')\n  canvas.width = Math.round(bmp.width * scale)\n  canvas.height = Math.round(bmp.height * scale)\n  canvas.getContext('2d')?.drawImage(bmp, 0, 0, canvas.width, canvas.height)\n  return canvas.toDataURL('image/jpeg', 0.8)\n}\n\nexport type FlagName = 'sound' | 'online' | 'motion'\nexport const getFlag = (name: FlagName): boolean => read(`sunset.${name}`) !== '0'\nexport function setFlag(name: FlagName, value: boolean) {\n  write(`sunset.${name}`, value ? '1' : '0')\n  if (name === 'motion') document.documentElement.dataset.motion = value ? 'on' : 'off'\n}\n",
 "src/features/chat/api.ts": "import { supabase } from '../../lib/supabase'\nimport type { ChatItem, LastMessage, MarketItem, Message, Profile, Reaction } from '../../lib/types'\n\nconst PROFILE_COLS = 'id, username, display_name, bio, avatar_url, created_at, showcase_number, showcase_handle'\nconst MESSAGE_COLS = 'id, chat_id, sender_id, body, reply_to, created_at, edited_at, forwarded_from'\n\nexport async function searchProfiles(query: string, myId: string): Promise<Profile[]> {\n  const q = query.toLowerCase().replace(/[^a-z0-9_]/g, '')\n  if (!q) return []\n  const { data, error } = await supabase\n    .from('profiles').select(PROFILE_COLS).ilike('username', `%${q}%`).neq('id', myId).limit(8)\n  if (error) throw error\n  return data as Profile[]\n}\n\nexport async function createDirectChat(otherId: string): Promise<string> {\n  const { data, error } = await supabase.rpc('create_direct_chat', { p_other: otherId })\n  if (error) throw error\n  return data as string\n}\n\ninterface MembershipRow { chat_id: string; chats: { kind: string; title: string | null } }\ninterface OtherRow { chat_id: string; profiles: Profile }\n\nexport async function listChats(myId: string): Promise<ChatItem[]> {\n  const { data: mine, error } = await supabase\n    .from('chat_members').select('chat_id, chats!inner(kind, title)').eq('user_id', myId)\n  if (error) throw error\n  const memberships = (mine ?? []) as unknown as MembershipRow[]\n  if (memberships.length === 0) return []\n\n  const { data: others, error: error2 } = await supabase\n    .from('chat_members').select(`chat_id, profiles!inner(${PROFILE_COLS})`)\n    .in('chat_id', memberships.map((m) => m.chat_id)).neq('user_id', myId)\n  if (error2) throw error2\n\n  const otherByChat = new Map<string, Profile>()\n  for (const o of (others ?? []) as unknown as OtherRow[]) {\n    if (!otherByChat.has(o.chat_id)) otherByChat.set(o.chat_id, o.profiles)\n  }\n  return memberships.map((m) => {\n    const other = otherByChat.get(m.chat_id)\n    const direct = m.chats.kind === 'direct'\n    return {\n      id: m.chat_id,\n      name: m.chats.title ?? other?.display_name ?? 'Чат',\n      username: direct ? (other?.username ?? null) : null,\n      avatarUrl: direct ? (other?.avatar_url ?? null) : null,\n      bio: direct ? (other?.bio ?? null) : null,\n      otherId: direct ? (other?.id ?? null) : null,\n      kind: m.chats.kind as ChatItem['kind'],\n      joinedAt: direct ? (other?.created_at ?? null) : null,\n      number: direct ? (other?.showcase_number ?? null) : null,\n      handle: direct ? (other?.showcase_handle ?? null) : null,\n    }\n  })\n}\n\nexport async function fetchMessages(chatId: string): Promise<Message[]> {\n  const { data, error } = await supabase\n    .from('messages').select(MESSAGE_COLS).eq('chat_id', chatId).is('deleted_at', null)\n    .order('created_at', { ascending: false }).limit(100)\n  if (error) throw error\n  return (data as Message[]).reverse()\n}\n\nexport async function sendMessage(\n  chatId: string, senderId: string, body: string, replyTo: string | null, forwardedFrom: string | null = null,\n): Promise<Message> {\n  const { data, error } = await supabase\n    .from('messages').insert({ chat_id: chatId, sender_id: senderId, body, reply_to: replyTo, forwarded_from: forwardedFrom })\n    .select(MESSAGE_COLS).single()\n  if (error) throw error\n  return data as Message\n}\n\nexport async function fetchReactions(messageIds: string[]): Promise<Reaction[]> {\n  if (messageIds.length === 0) return []\n  const { data, error } = await supabase\n    .from('reactions').select('message_id, user_id, emoji').in('message_id', messageIds)\n  if (error) throw error\n  return data as Reaction[]\n}\n\nexport async function addReaction(r: Reaction): Promise<void> {\n  const { error } = await supabase.from('reactions').insert(r)\n  if (error) throw error\n}\n\nexport async function removeReaction(r: Reaction): Promise<void> {\n  const { error } = await supabase.from('reactions').delete()\n    .eq('message_id', r.message_id).eq('user_id', r.user_id).eq('emoji', r.emoji)\n  if (error) throw error\n}\n\nexport async function unreadCounts(): Promise<Record<string, number>> {\n  const { data, error } = await supabase.rpc('unread_counts')\n  if (error) throw error\n  const rows = (data ?? []) as { chat_id: string; unread: number | string }[]\n  return Object.fromEntries(rows.map((r) => [r.chat_id, Number(r.unread)]))\n}\n\nexport async function markRead(chatId: string): Promise<void> {\n  const { error } = await supabase.rpc('mark_chat_read', { p_chat: chatId })\n  if (error) throw error\n}\n\nexport async function uploadAvatar(userId: string, file: File): Promise<string> {\n  const types: Record<string, string> = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp' }\n  const ext = types[file.type]\n  if (!ext) throw new Error('Только PNG, JPG или WebP.')\n  if (file.size > 2 * 1024 * 1024) throw new Error('Файл больше 2 МБ.')\n  const path = `${userId}/avatar-${Date.now()}.${ext}`\n  const { error } = await supabase.storage.from('avatars').upload(path, file, { contentType: file.type })\n  if (error) throw error\n  return supabase.storage.from('avatars').getPublicUrl(path).data.publicUrl\n}\n\nexport async function updateProfile(\n  id: string,\n  patch: { display_name: string; bio: string | null; avatar_url: string | null },\n): Promise<Profile> {\n  const { data, error } = await supabase.from('profiles').update(patch).eq('id', id).select(PROFILE_COLS).single()\n  if (error) throw error\n  return data as Profile\n}\n\nexport async function getSavedChat(): Promise<string> {\n  const { data, error } = await supabase.rpc('get_saved_chat')\n  if (error) throw error\n  return data as string\n}\n\nexport async function lastMessages(): Promise<Record<string, LastMessage>> {\n  const { data, error } = await supabase.rpc('last_messages')\n  if (error) throw error\n  const rows = (data ?? []) as (LastMessage & { chat_id: string })[]\n  return Object.fromEntries(rows.map((r) => [r.chat_id, { body: r.body, created_at: r.created_at, sender_id: r.sender_id }]))\n}\n\nexport async function updateMessage(id: string, body: string): Promise<void> {\n  const { error } = await supabase.from('messages').update({ body, edited_at: new Date().toISOString() }).eq('id', id)\n  if (error) throw error\n}\n\nexport async function deleteMessage(id: string): Promise<void> {\n  const { error } = await supabase.from('messages').update({ deleted_at: new Date().toISOString() }).eq('id', id)\n  if (error) throw error\n}\n\nexport async function fetchPin(chatId: string): Promise<string | null> {\n  const { data, error } = await supabase.from('chat_pins').select('message_id').eq('chat_id', chatId).maybeSingle()\n  if (error) throw error\n  return (data as { message_id: string } | null)?.message_id ?? null\n}\n\nexport async function setPin(chatId: string, messageId: string, userId: string): Promise<void> {\n  const { error } = await supabase.from('chat_pins').upsert({ chat_id: chatId, message_id: messageId, pinned_by: userId })\n  if (error) throw error\n}\n\nexport async function clearPin(chatId: string): Promise<void> {\n  const { error } = await supabase.from('chat_pins').delete().eq('chat_id', chatId)\n  if (error) throw error\n}\n\nexport async function fetchPeerRead(chatId: string, peerId: string): Promise<string | null> {\n  const { data, error } = await supabase.from('chat_members').select('last_read_at')\n    .eq('chat_id', chatId).eq('user_id', peerId).maybeSingle()\n  if (error) throw error\n  return (data as { last_read_at: string } | null)?.last_read_at ?? null\n}\n\n// ---------- Маркет ----------\nconst ITEM_COLS = 'id, kind, value, owner_id, price'\n\nasync function rpcVoid(fn: string, args?: Record<string, unknown>): Promise<void> {\n  const { error } = await supabase.rpc(fn, args)\n  if (error) throw error\n}\n\nexport async function getStars(): Promise<number> {\n  const { data, error } = await supabase.rpc('my_stars')\n  if (error) throw error\n  return Number(data ?? 0)\n}\n\nexport async function listMarket(): Promise<MarketItem[]> {\n  const { data, error } = await supabase.from('market_items').select(ITEM_COLS).not('price', 'is', null).order('price')\n  if (error) throw error\n  return data as MarketItem[]\n}\n\nexport async function myItems(userId: string): Promise<MarketItem[]> {\n  const { data, error } = await supabase.from('market_items').select(ITEM_COLS).eq('owner_id', userId).order('created_at')\n  if (error) throw error\n  return data as MarketItem[]\n}\n\nexport const buyItem = (id: string) => rpcVoid('market_buy', { p_item: id })\nexport const listItem = (id: string, price: number) => rpcVoid('market_list', { p_item: id, p_price: price })\nexport const unlistItem = (id: string) => rpcVoid('market_unlist', { p_item: id })\nexport const applyItem = (id: string) => rpcVoid('market_apply', { p_item: id })\nexport const unapplyItem = (kind: MarketItem['kind']) => rpcVoid('market_unapply', { p_kind: kind })\n",
 "src/features/chat/hooks.ts": "import { useCallback, useEffect, useMemo, useRef, useState } from 'react'\nimport type { RealtimeChannel } from '@supabase/supabase-js'\nimport { supabase } from '../../lib/supabase'\nimport { getFlag, getMuted, playBeep } from '../../lib/prefs'\nimport type { ChatItem, LastMessage, Message, Reaction } from '../../lib/types'\nimport {\n  addReaction, fetchMessages, fetchPeerRead, fetchPin, fetchReactions, getSavedChat, lastMessages, listChats,\n  markRead, removeReaction, unreadCounts,\n} from './api'\n\nexport function useChats(myId: string, selectedId: string | null) {\n  const [chats, setChats] = useState<ChatItem[]>([])\n  const [unread, setUnread] = useState<Record<string, number>>({})\n  const [last, setLast] = useState<Record<string, LastMessage>>({})\n  const [loading, setLoading] = useState(true)\n  const selectedRef = useRef(selectedId)\n\n  useEffect(() => { selectedRef.current = selectedId }, [selectedId])\n\n  const reload = useCallback(async () => {\n    try { setChats(await listChats(myId)) }\n    catch (e) { console.error('listChats failed', e) }\n    finally { setLoading(false) }\n  }, [myId])\n\n  const loadMeta = useCallback(async () => {\n    try {\n      const [u, l] = await Promise.all([unreadCounts(), lastMessages()])\n      setUnread(u)\n      setLast(l)\n    } catch (e) { console.error('loadMeta failed', e) }\n  }, [])\n\n  useEffect(() => {\n    void getSavedChat().catch((e) => console.error('getSavedChat failed', e)).then(() => reload())\n    void loadMeta()\n    const channel = supabase\n      .channel(`my-chats:${myId}`)\n      .on('postgres_changes',\n        { event: 'INSERT', schema: 'public', table: 'chat_members', filter: `user_id=eq.${myId}` },\n        () => { void reload(); void loadMeta() })\n      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages' }, (payload) => {\n        const m = payload.new as Message\n        if (m.sender_id !== myId) {\n          const isOpen = m.chat_id === selectedRef.current && !document.hidden\n          if (!isOpen && getFlag('sound') && !getMuted().includes(m.chat_id)) playBeep()\n          if (m.chat_id === selectedRef.current) { void markRead(m.chat_id).then(loadMeta); return }\n        }\n        void loadMeta()\n      })\n      .subscribe()\n    return () => { void supabase.removeChannel(channel) }\n  }, [myId, reload, loadMeta])\n\n  useEffect(() => {\n    if (selectedId) void markRead(selectedId).then(loadMeta).catch(() => undefined)\n  }, [selectedId, loadMeta])\n\n  const sorted = useMemo(() => [...chats].sort((a, b) => {\n    if (a.kind === 'saved') return -1\n    if (b.kind === 'saved') return 1\n    return (last[b.id]?.created_at ?? '9999').localeCompare(last[a.id]?.created_at ?? '9999')\n  }), [chats, last])\n\n  return { chats: sorted, loading, unread, last, reload }\n}\n\nexport function useOnline(myId: string, visible: boolean) {\n  const [online, setOnline] = useState<Set<string>>(new Set())\n  useEffect(() => {\n    const channel = supabase.channel('online', { config: { presence: { key: myId } } })\n    channel\n      .on('presence', { event: 'sync' }, () => setOnline(new Set(Object.keys(channel.presenceState()))))\n      .subscribe((status) => { if (status === 'SUBSCRIBED' && visible) void channel.track({ at: Date.now() }) })\n    return () => { void supabase.removeChannel(channel) }\n  }, [myId, visible])\n  return online\n}\n\nconst rKey = (r: Reaction) => `${r.message_id}|${r.user_id}|${r.emoji}`\n\nfunction mergeMessages(a: Message[], b: Message[]): Message[] {\n  const byId = new Map<string, Message>()\n  for (const m of [...a, ...b]) byId.set(m.id, m)\n  return [...byId.values()].sort((x, y) => x.created_at.localeCompare(y.created_at))\n}\n\nfunction mergeReactions(a: Reaction[], b: Reaction[]): Reaction[] {\n  const map = new Map<string, Reaction>()\n  for (const r of [...a, ...b]) map.set(rKey(r), r)\n  return [...map.values()]\n}\n\nexport function useMessages(chatId: string, myId: string, peerId: string | null) {\n  const [messages, setMessages] = useState<Message[]>([])\n  const [reactions, setReactions] = useState<Reaction[]>([])\n  const [typing, setTyping] = useState(false)\n  const [pinId, setPinId] = useState<string | null>(null)\n  const [peerReadAt, setPeerReadAt] = useState<string | null>(null)\n  const [loading, setLoading] = useState(true)\n  const [error, setError] = useState<string | null>(null)\n  const channelRef = useRef<RealtimeChannel | null>(null)\n  const lastTypingSent = useRef(0)\n  const typingTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)\n\n  const add = useCallback((m: Message) => setMessages((prev) => mergeMessages(prev, [m])), [])\n  const patch = useCallback((m: Message) => setMessages((prev) => prev.map((x) => (x.id === m.id ? { ...x, ...m } : x))), [])\n  const remove = useCallback((id: string) => setMessages((prev) => prev.filter((x) => x.id !== id)), [])\n\n  useEffect(() => {\n    let active = true\n    setMessages([]); setReactions([]); setTyping(false); setPinId(null); setPeerReadAt(null); setLoading(true); setError(null)\n\n    fetchMessages(chatId)\n      .then(async (data) => {\n        if (!active) return\n        setMessages((prev) => mergeMessages(data, prev))\n        const r = await fetchReactions(data.map((m) => m.id))\n        if (active) setReactions((prev) => mergeReactions(r, prev))\n      })\n      .catch((e: Error) => { if (active) setError(e.message) })\n      .finally(() => { if (active) setLoading(false) })\n    fetchPin(chatId).then((id) => { if (active) setPinId(id) }).catch(() => undefined)\n    if (peerId) fetchPeerRead(chatId, peerId).then((t) => { if (active) setPeerReadAt(t) }).catch(() => undefined)\n\n    const channel = supabase\n      .channel(`chat:${chatId}`)\n      .on('postgres_changes',\n        { event: 'INSERT', schema: 'public', table: 'messages', filter: `chat_id=eq.${chatId}` },\n        (payload) => { setTyping(false); add(payload.new as Message) })\n      .on('postgres_changes',\n        { event: 'UPDATE', schema: 'public', table: 'messages', filter: `chat_id=eq.${chatId}` },\n        (payload) => {\n          const m = payload.new as Message & { deleted_at: string | null }\n          if (m.deleted_at) remove(m.id)\n          else patch(m)\n        })\n      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'reactions' },\n        (payload) => setReactions((prev) => mergeReactions(prev, [payload.new as Reaction])))\n      .on('postgres_changes', { event: 'DELETE', schema: 'public', table: 'reactions' }, (payload) => {\n        const old = payload.old as Partial<Reaction>\n        if (old.message_id && old.user_id && old.emoji) {\n          const key = rKey(old as Reaction)\n          setReactions((prev) => prev.filter((r) => rKey(r) !== key))\n        }\n      })\n      .on('postgres_changes', { event: '*', schema: 'public', table: 'chat_pins' }, (payload) => {\n        const del = payload.eventType === 'DELETE'\n        const row = (del ? payload.old : payload.new) as { chat_id?: string; message_id?: string }\n        if (row.chat_id === chatId) setPinId(del ? null : (row.message_id ?? null))\n      })\n      .on('postgres_changes',\n        { event: 'UPDATE', schema: 'public', table: 'chat_members', filter: `chat_id=eq.${chatId}` },\n        (payload) => {\n          const r = payload.new as { user_id?: string; last_read_at?: string }\n          if (peerId && r.user_id === peerId && r.last_read_at) setPeerReadAt(r.last_read_at)\n        })\n      .on('broadcast', { event: 'typing' }, (msg) => {\n        const uid = (msg.payload as { userId?: string } | undefined)?.userId\n        if (!uid || uid === myId) return\n        setTyping(true)\n        clearTimeout(typingTimer.current)\n        typingTimer.current = setTimeout(() => setTyping(false), 3000)\n      })\n      .subscribe()\n    channelRef.current = channel\n\n    return () => {\n      active = false\n      clearTimeout(typingTimer.current)\n      channelRef.current = null\n      void supabase.removeChannel(channel)\n    }\n  }, [chatId, myId, peerId, add, patch, remove])\n\n  const sendTyping = useCallback(() => {\n    const now = Date.now()\n    if (now - lastTypingSent.current < 2000) return\n    lastTypingSent.current = now\n    void channelRef.current?.send({ type: 'broadcast', event: 'typing', payload: { userId: myId } })\n  }, [myId])\n\n  const toggleReaction = useCallback(async (messageId: string, emoji: string) => {\n    const r: Reaction = { message_id: messageId, user_id: myId, emoji }\n    const exists = reactions.some((x) => rKey(x) === rKey(r))\n    if (exists) setReactions((prev) => prev.filter((x) => rKey(x) !== rKey(r)))\n    else setReactions((prev) => mergeReactions(prev, [r]))\n    try {\n      if (exists) await removeReaction(r)\n      else await addReaction(r)\n    } catch {\n      if (exists) setReactions((prev) => mergeReactions(prev, [r]))\n      else setReactions((prev) => prev.filter((x) => rKey(x) !== rKey(r)))\n    }\n  }, [reactions, myId])\n\n  return {\n    messages, reactions, typing, pinId, peerReadAt, loading, error,\n    add, patch, remove, setPinId, sendTyping, toggleReaction,\n  }\n}\n",
 "src/features/chat/MessageMenu.tsx": "import { Check, CheckCheck, Copy, Forward, Pencil, Pin, Reply, Trash2, type LucideIcon } from 'lucide-react'\n\nexport type MenuAction = 'reply' | 'edit' | 'pin' | 'copy' | 'forward' | 'delete' | 'select'\n\ninterface Props {\n  x: number\n  y: number\n  mine: boolean\n  pinned: boolean\n  emojis: string[]\n  time: string\n  read: boolean | null\n  onReact: (emoji: string) => void\n  onAction: (a: MenuAction) => void\n  onClose: () => void\n}\n\ninterface Item { k: MenuAction; label: string; Icon: LucideIcon; danger?: boolean }\n\nexport default function MessageMenu({ x, y, mine, pinned, emojis, time, read, onReact, onAction, onClose }: Props) {\n  const items: Item[] = [\n    { k: 'reply', label: 'Ответить', Icon: Reply },\n    ...(mine ? [{ k: 'edit', label: 'Изменить', Icon: Pencil } as Item] : []),\n    { k: 'pin', label: pinned ? 'Открепить' : 'Закрепить', Icon: Pin },\n    { k: 'copy', label: 'Копировать текст', Icon: Copy },\n    { k: 'forward', label: 'Переслать', Icon: Forward },\n    ...(mine ? [{ k: 'delete', label: 'Удалить', Icon: Trash2, danger: true } as Item] : []),\n    { k: 'select', label: 'Выделить', Icon: Check },\n  ]\n  const left = Math.max(8, Math.min(x, window.innerWidth - 268))\n  const top = Math.max(8, Math.min(y, window.innerHeight - 430))\n\n  return (\n    <div className=\"fixed inset-0 z-40\" onClick={onClose} onContextMenu={(e) => { e.preventDefault(); onClose() }}>\n      <div className=\"absolute w-64 space-y-2\" style={{ left, top }} onClick={(e) => e.stopPropagation()}>\n        <div className=\"flex justify-between rounded-full border border-line bg-bg2 px-2 py-1 shadow-lg\">\n          {emojis.map((e) => (\n            <button key={e} onClick={() => onReact(e)} className=\"rounded-full px-1 text-xl transition hover:scale-125\">{e}</button>\n          ))}\n        </div>\n        <div className=\"overflow-hidden rounded-2xl border border-line bg-bg2 py-1 shadow-lg\">\n          {items.map(({ k, label, Icon, danger }) => (\n            <button key={k} onClick={() => onAction(k)}\n              className={`flex w-full items-center gap-3 px-4 py-2.5 text-sm transition hover:bg-surface ${danger ? 'text-pink' : ''}`}>\n              <Icon size={18} className={danger ? '' : 'text-muted'} />{label}\n            </button>\n          ))}\n          <div className=\"mt-1 flex items-center gap-2 border-t border-line px-4 py-2.5 text-xs text-muted\">\n            {read === null ? null : read ? <CheckCheck size={14} className=\"text-accent\" /> : <Check size={14} />}\n            {time}\n          </div>\n        </div>\n      </div>\n    </div>\n  )\n}\n",
 "src/features/chat/ForwardModal.tsx": "import type { ChatItem } from '../../lib/types'\nimport ChatAvatar from './ChatAvatar'\n\ninterface Props { chats: ChatItem[]; count: number; onPick: (chat: ChatItem) => void; onClose: () => void }\n\nexport default function ForwardModal({ chats, count, onPick, onClose }: Props) {\n  return (\n    <div className=\"fixed inset-0 z-40 flex items-center justify-center bg-black/60 p-4\" onClick={onClose}>\n      <div className=\"w-full max-w-sm rounded-3xl bg-bg2 p-4\" onClick={(e) => e.stopPropagation()}>\n        <h2 className=\"px-2 pb-3 text-lg font-medium\">Переслать ({count})</h2>\n        <div className=\"max-h-80 overflow-y-auto\">\n          {chats.map((c) => (\n            <button key={c.id} onClick={() => onPick(c)}\n              className=\"flex w-full items-center gap-3 rounded-xl p-3 text-left transition hover:bg-surface\">\n              <ChatAvatar chat={c} />\n              <span className=\"truncate text-sm font-medium\">{c.name}</span>\n            </button>\n          ))}\n        </div>\n      </div>\n    </div>\n  )\n}\n",
 "src/features/chat/ChatView.tsx": "import { useEffect, useMemo, useRef, useState, type FormEvent, type MouseEvent, type TouchEvent } from 'react'\nimport { ArrowLeft, Check, CheckCheck, Copy, Forward, PanelRight, Pencil, Pin, Reply, SendHorizontal, Trash2, X } from 'lucide-react'\nimport type { ChatItem, Message } from '../../lib/types'\nimport { clearPin, deleteMessage, sendMessage, setPin, updateMessage } from './api'\nimport { useMessages } from './hooks'\nimport ChatAvatar from './ChatAvatar'\nimport ForwardModal from './ForwardModal'\nimport MessageMenu, { type MenuAction } from './MessageMenu'\n\nconst EMOJIS = ['👍', '❤️', '😂', '🔥', '😮', '😢']\n\ninterface Props {\n  chat: ChatItem\n  chats: ChatItem[]\n  myId: string\n  myName: string\n  online: boolean\n  background: string | null\n  onBack: () => void\n  onToggleInfo: () => void\n}\n\nfunction formatFull(iso: string): string {\n  const d = new Date(iso)\n  const now = new Date()\n  const yesterday = new Date(now)\n  yesterday.setDate(now.getDate() - 1)\n  const time = d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })\n  if (d.toDateString() === now.toDateString()) return `сегодня в ${time}`\n  if (d.toDateString() === yesterday.toDateString()) return `вчера в ${time}`\n  return `${d.toLocaleDateString([], { day: 'numeric', month: 'short' })} в ${time}`\n}\n\nexport default function ChatView({ chat, chats, myId, myName, online, background, onBack, onToggleInfo }: Props) {\n  const {\n    messages, reactions, typing, pinId, peerReadAt, loading, error, add, patch, remove, setPinId, sendTyping, toggleReaction,\n  } = useMessages(chat.id, myId, chat.otherId)\n  const [text, setText] = useState('')\n  const [replyTo, setReplyTo] = useState<Message | null>(null)\n  const [editing, setEditing] = useState<Message | null>(null)\n  const [menu, setMenu] = useState<{ x: number; y: number; m: Message } | null>(null)\n  const [selectMode, setSelectMode] = useState(false)\n  const [selected, setSelected] = useState<Set<string>>(new Set())\n  const [forwarding, setForwarding] = useState<Message[] | null>(null)\n  const [sendError, setSendError] = useState<string | null>(null)\n  const endRef = useRef<HTMLDivElement>(null)\n  const pressTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)\n  const saved = chat.kind === 'saved'\n  const direct = chat.kind === 'direct'\n\n  useEffect(() => { endRef.current?.scrollIntoView({ behavior: 'smooth' }) }, [messages.length])\n\n  const byMessage = useMemo(() => {\n    const map = new Map<string, Map<string, string[]>>()\n    for (const r of reactions) {\n      const emojis = map.get(r.message_id) ?? new Map<string, string[]>()\n      emojis.set(r.emoji, [...(emojis.get(r.emoji) ?? []), r.user_id])\n      map.set(r.message_id, emojis)\n    }\n    return map\n  }, [reactions])\n\n  const status = typing ? 'печатает…' : saved ? 'Только для вас' : online ? 'в сети' : chat.username ? `@${chat.username}` : ''\n  const pinned = pinId ? messages.find((m) => m.id === pinId) : undefined\n  const selectedMessages = messages.filter((m) => selected.has(m.id))\n  const fail = (e: unknown) => setSendError((e as Error).message)\n  const isRead = (m: Message) => peerReadAt !== null && Date.parse(peerReadAt) >= Date.parse(m.created_at)\n  const senderName = (m: Message) => (m.sender_id === myId ? myName : chat.name)\n\n  function exitSelect() { setSelectMode(false); setSelected(new Set()) }\n  function toggleSelect(id: string) {\n    setSelected((prev) => {\n      const next = new Set(prev)\n      if (next.has(id)) next.delete(id)\n      else next.add(id)\n      return next\n    })\n  }\n\n  function openMenu(e: MouseEvent, m: Message) {\n    e.preventDefault()\n    if (!selectMode) setMenu({ x: e.clientX, y: e.clientY, m })\n  }\n  function startPress(e: TouchEvent, m: Message) {\n    const t = e.touches[0]\n    pressTimer.current = setTimeout(() => { if (!selectMode) setMenu({ x: t.clientX, y: t.clientY, m }) }, 450)\n  }\n  const cancelPress = () => clearTimeout(pressTimer.current)\n\n  async function removeMessages(list: Message[]) {\n    for (const m of list) {\n      try { await deleteMessage(m.id); remove(m.id) } catch (e) { fail(e) }\n    }\n  }\n\n  async function onAction(kind: MenuAction, m: Message) {\n    setMenu(null)\n    if (kind === 'reply') { setReplyTo(m); setEditing(null) }\n    else if (kind === 'edit') { setEditing(m); setReplyTo(null); setText(m.body ?? '') }\n    else if (kind === 'copy') void navigator.clipboard.writeText(m.body ?? '')\n    else if (kind === 'forward') setForwarding([m])\n    else if (kind === 'delete') await removeMessages([m])\n    else if (kind === 'select') { setSelectMode(true); setSelected(new Set([m.id])) }\n    else if (kind === 'pin') {\n      try {\n        if (pinId === m.id) { await clearPin(chat.id); setPinId(null) }\n        else { await setPin(chat.id, m.id, myId); setPinId(m.id) }\n      } catch (e) { fail(e) }\n    }\n  }\n\n  async function doForward(target: ChatItem) {\n    const list = forwarding ?? []\n    setForwarding(null)\n    exitSelect()\n    for (const m of list) {\n      try { await sendMessage(target.id, myId, m.body ?? '', null, m.forwarded_from ?? senderName(m)) } catch (e) { fail(e) }\n    }\n  }\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault()\n    const body = text.trim()\n    if (!body) return\n    setSendError(null)\n    if (editing) {\n      const target = editing\n      setText(''); setEditing(null)\n      try { await updateMessage(target.id, body); patch({ ...target, body, edited_at: new Date().toISOString() }) }\n      catch (err) { fail(err); setText(body); setEditing(target) }\n      return\n    }\n    const reply = replyTo\n    setText(''); setReplyTo(null)\n    try { add(await sendMessage(chat.id, myId, body, reply?.id ?? null)) }\n    catch (err) { fail(err); setText(body); setReplyTo(reply) }\n  }\n\n  const headerInfo = (\n    <>\n      <ChatAvatar chat={chat} size={40} online={online} />\n      <div className=\"min-w-0 text-left\">\n        <div className=\"truncate text-sm font-medium\">{chat.name}</div>\n        <div className={`truncate text-xs ${typing || online ? 'text-accent' : 'text-muted'}`}>{status}</div>\n      </div>\n    </>\n  )\n  const barBtn = 'rounded-lg p-2 text-muted transition hover:bg-surface hover:text-text'\n  const allMine = selectedMessages.length > 0 && selectedMessages.every((m) => m.sender_id === myId)\n\n  return (\n    <section className=\"flex h-full min-w-0 flex-1 flex-col bg-bg\">\n      <header className=\"flex items-center gap-3 border-b border-line bg-bg2 px-4 py-3\">\n        {selectMode ? (\n          <>\n            <button onClick={exitSelect} title=\"Отмена\" className={barBtn}><X size={18} /></button>\n            <div className=\"flex-1 text-sm font-medium\">Выбрано: {selected.size}</div>\n            <button title=\"Копировать\" disabled={selected.size === 0} className={barBtn}\n              onClick={() => { void navigator.clipboard.writeText(selectedMessages.map((m) => m.body ?? '').join('\\n')); exitSelect() }}>\n              <Copy size={18} />\n            </button>\n            <button title=\"Переслать\" disabled={selected.size === 0} className={barBtn} onClick={() => setForwarding(selectedMessages)}>\n              <Forward size={18} />\n            </button>\n            {allMine && (\n              <button title=\"Удалить\" className={`${barBtn} text-pink`} onClick={() => { void removeMessages(selectedMessages); exitSelect() }}>\n                <Trash2 size={18} />\n              </button>\n            )}\n          </>\n        ) : (\n          <>\n            <button onClick={onBack} className=\"rounded-lg p-1 text-muted hover:text-text md:hidden\"><ArrowLeft size={20} /></button>\n            {saved ? (\n              <div className=\"flex min-w-0 flex-1 items-center gap-3\">{headerInfo}</div>\n            ) : (\n              <>\n                <button onClick={onToggleInfo} className=\"flex min-w-0 flex-1 items-center gap-3\">{headerInfo}</button>\n                <button onClick={onToggleInfo} title=\"Информация\" className={barBtn}><PanelRight size={18} /></button>\n              </>\n            )}\n          </>\n        )}\n      </header>\n\n      {pinId && (\n        <div className=\"flex items-center gap-3 border-b border-line bg-bg2 px-4 py-2 text-sm\">\n          <Pin size={14} className=\"shrink-0 text-accent\" />\n          <button className=\"min-w-0 flex-1 truncate text-left\"\n            onClick={() => document.getElementById(`msg-${pinId}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' })}>\n            <span className=\"text-xs text-accent\">Закреплено · </span>{pinned?.body ?? 'сообщение'}\n          </button>\n          <button title=\"Открепить\" className=\"text-muted hover:text-text\"\n            onClick={() => void clearPin(chat.id).then(() => setPinId(null)).catch(fail)}><X size={14} /></button>\n        </div>\n      )}\n\n      <div className=\"relative flex-1 overflow-hidden\">\n        {background && <div className=\"absolute inset-0 bg-cover bg-center\" style={{ backgroundImage: `url(${background})` }} />}\n        {background && <div className=\"absolute inset-0 bg-bg/40\" />}\n        <div className=\"relative h-full space-y-3 overflow-y-auto p-4\">\n          {loading && <div className=\"h-10 w-48 animate-pulse rounded-2xl bg-surface\" />}\n          {error && <p className=\"text-sm text-pink\">Не удалось загрузить: {error}</p>}\n          {!loading && !error && messages.length === 0 && (\n            <p className=\"pt-10 text-center text-sm text-muted\">\n              {saved ? 'Сохраняй сюда заметки и важное.' : 'Сообщений пока нет. Напиши первым.'}\n            </p>\n          )}\n          {messages.map((m) => {\n            const mine = m.sender_id === myId\n            const original = m.reply_to ? messages.find((x) => x.id === m.reply_to) : null\n            const chips = byMessage.get(m.id)\n            const ticks = mine && direct\n            return (\n              <div key={m.id} id={`msg-${m.id}`} className={`flex ${mine ? 'justify-end' : 'justify-start'}`}\n                onClick={() => { if (selectMode) toggleSelect(m.id) }}>\n                <div className=\"relative max-w-[75%]\">\n                  <div onContextMenu={(e) => openMenu(e, m)} onTouchStart={(e) => startPress(e, m)}\n                    onTouchEnd={cancelPress} onTouchMove={cancelPress}\n                    className={`rounded-2xl px-4 py-2 text-sm select-none md:select-text ${\n                      mine ? 'rounded-br-md bg-accent text-on-accent' : 'rounded-bl-md bg-surface'} ${\n                      selected.has(m.id) ? 'ring-2 ring-text' : ''}`}>\n                    {m.forwarded_from && (\n                      <div className={`mb-1 text-xs ${mine ? 'text-on-accent/80' : 'text-accent'}`}>Переслано от {m.forwarded_from}</div>\n                    )}\n                    {m.reply_to && (\n                      <div className={`mb-1 truncate border-l-2 pl-2 text-xs ${\n                        mine ? 'border-on-accent/50 text-on-accent/80' : 'border-accent text-muted'}`}>\n                        {original?.body ?? 'Сообщение'}\n                      </div>\n                    )}\n                    <p className=\"break-words whitespace-pre-wrap\">{m.body}</p>\n                    <div className={`mt-1 flex items-center justify-end gap-1 text-[10px] ${mine ? 'text-on-accent/70' : 'text-muted'}`}>\n                      {m.edited_at && <span>изменено</span>}\n                      {new Date(m.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}\n                      {ticks && (isRead(m) ? <CheckCheck size={12} /> : <Check size={12} />)}\n                    </div>\n                  </div>\n                  {chips && (\n                    <div className={`mt-1 flex flex-wrap gap-1 ${mine ? 'justify-end' : ''}`}>\n                      {[...chips].map(([emoji, users]) => (\n                        <button key={emoji} onClick={() => void toggleReaction(m.id, emoji)}\n                          className={`rounded-full px-2 py-0.5 text-xs transition ${\n                            users.includes(myId) ? 'bg-accent/30 ring-1 ring-accent' : 'bg-surface'}`}>\n                          {emoji} {users.length}\n                        </button>\n                      ))}\n                    </div>\n                  )}\n                </div>\n              </div>\n            )\n          })}\n          <div ref={endRef} />\n        </div>\n      </div>\n\n      <form onSubmit={onSubmit} className=\"border-t border-line bg-bg2 p-3\">\n        {(replyTo || editing) && (\n          <div className=\"mb-2 flex items-center gap-2 rounded-xl bg-surface px-3 py-2 text-xs\">\n            {editing ? <Pencil size={14} className=\"text-accent\" /> : <Reply size={14} className=\"text-accent\" />}\n            <span className=\"flex-1 truncate text-muted\">{editing ? `Изменение: ${editing.body ?? ''}` : replyTo?.body}</span>\n            <button type=\"button\" className=\"text-muted hover:text-text\"\n              onClick={() => { setReplyTo(null); if (editing) { setEditing(null); setText('') } }}><X size={14} /></button>\n          </div>\n        )}\n        {sendError && <p className=\"mb-2 text-xs text-pink\">Ошибка: {sendError}</p>}\n        <div className=\"flex items-center gap-2 rounded-2xl bg-surface px-4 py-1.5\">\n          <input value={text} maxLength={4000} placeholder=\"Сообщение\"\n            onChange={(e) => { setText(e.target.value); if (e.target.value && !saved && !editing) sendTyping() }}\n            className=\"flex-1 bg-transparent py-2 text-sm outline-none placeholder:text-muted\" />\n          <button type=\"submit\" disabled={!text.trim()} title={editing ? 'Сохранить' : 'Отправить'}\n            className=\"rounded-xl p-2 text-accent transition hover:bg-bg2 disabled:opacity-40\">\n            {editing ? <Check size={20} /> : <SendHorizontal size={20} />}\n          </button>\n        </div>\n      </form>\n\n      {menu && (\n        <MessageMenu x={menu.x} y={menu.y} mine={menu.m.sender_id === myId} pinned={pinId === menu.m.id} emojis={EMOJIS}\n          time={formatFull(menu.m.created_at)} read={menu.m.sender_id === myId && direct ? isRead(menu.m) : null}\n          onReact={(e) => { void toggleReaction(menu.m.id, e); setMenu(null) }}\n          onAction={(a) => void onAction(a, menu.m)} onClose={() => setMenu(null)} />\n      )}\n      {forwarding && (\n        <ForwardModal chats={chats} count={forwarding.length} onPick={(c) => void doForward(c)} onClose={() => setForwarding(null)} />\n      )}\n    </section>\n  )\n}\n",
 "src/features/chat/RightPanel.tsx": "import { useState } from 'react'\nimport { Bell, BellOff, Check, Copy, MessageCircle, X } from 'lucide-react'\nimport type { ChatItem } from '../../lib/types'\nimport ChatAvatar from './ChatAvatar'\n\ninterface Props {\n  chat: ChatItem\n  online: boolean\n  muted: boolean\n  onToggleMute: () => void\n  onClose: () => void\n}\n\nconst action = 'flex flex-1 flex-col items-center gap-1 rounded-xl bg-surface py-3 text-xs transition hover:brightness-110'\n\nfunction Row({ label, value }: { label: string; value: string }) {\n  return (\n    <div className=\"px-4 py-3\">\n      <div className=\"text-xs text-muted\">{label}</div>\n      <div className=\"text-sm break-words whitespace-pre-wrap\">{value}</div>\n    </div>\n  )\n}\n\nexport default function RightPanel({ chat, online, muted, onToggleMute, onClose }: Props) {\n  const [copied, setCopied] = useState(false)\n\n  function copyUsername() {\n    if (!chat.username) return\n    void navigator.clipboard.writeText(`@${chat.username}`).then(() => {\n      setCopied(true)\n      setTimeout(() => setCopied(false), 1500)\n    })\n  }\n\n  return (\n    <aside className=\"fixed inset-y-0 right-0 z-20 flex w-80 flex-col gap-4 overflow-y-auto border-l border-line bg-bg2 p-5 lg:static lg:z-auto\">\n      <button onClick={onClose} title=\"Закрыть\" className=\"self-end rounded-lg p-1 text-muted transition hover:text-text\">\n        <X size={18} />\n      </button>\n      <div className=\"flex flex-col items-center gap-2\">\n        <ChatAvatar chat={chat} size={96} online={online} />\n        <div className=\"text-lg font-semibold\">{chat.name}</div>\n        <div className={`text-sm ${online ? 'text-accent' : 'text-muted'}`}>{online ? 'в сети' : 'не в сети'}</div>\n      </div>\n\n      <div className=\"flex gap-2\">\n        <button onClick={onClose} className={action}><MessageCircle size={20} />Чат</button>\n        <button onClick={onToggleMute} className={action}>\n          {muted ? <BellOff size={20} /> : <Bell size={20} />}{muted ? 'Без звука' : 'Звук'}\n        </button>\n        <button onClick={copyUsername} className={action}>\n          {copied ? <Check size={20} /> : <Copy size={20} />}{copied ? 'Готово' : 'Копировать'}\n        </button>\n      </div>\n\n      <div className=\"divide-y divide-line rounded-xl bg-surface\">\n        <Row label=\"Имя\" value={chat.name} />\n        {chat.username && <Row label=\"Username\" value={`@${chat.username}`} />}\n        {chat.number && <Row label=\"Номер\" value={chat.number} />}\n        {chat.handle && <Row label=\"Коллекционный юзернейм\" value={`@${chat.handle}`} />}\n        <Row label=\"О себе\" value={chat.bio || 'Описание не указано.'} />\n        {chat.joinedAt && (\n          <Row label=\"В SUNSET с\" value={new Date(chat.joinedAt).toLocaleDateString([], { day: 'numeric', month: 'long', year: 'numeric' })} />\n        )}\n      </div>\n    </aside>\n  )\n}\n",
 "src/features/settings/MarketPage.tsx": "import { useCallback, useEffect, useState } from 'react'\nimport { Star } from 'lucide-react'\nimport type { MarketItem, Profile } from '../../lib/types'\nimport { applyItem, buyItem, getStars, listItem, listMarket, myItems, unapplyItem, unlistItem } from '../chat/api'\n\ninterface Props { me: Profile; onProfileChanged: () => void }\n\nfunction friendly(msg: string): string {\n  if (msg.includes('not enough stars')) return 'Недостаточно Звёзд.'\n  if (msg.includes('not for sale')) return 'Лот уже недоступен.'\n  if (msg.includes('already yours')) return 'Это уже ваш лот.'\n  if (msg.includes('bad price')) return 'Цена от 1 до 1 000 000 000.'\n  if (msg.includes('unlist first')) return 'Сначала снимите лот с продажи.'\n  return msg\n}\n\nconst show = (it: MarketItem) => (it.kind === 'username' ? `@${it.value}` : it.value)\nconst chip = (active: boolean) =>\n  `rounded-lg px-3 py-1.5 text-sm transition ${active ? 'bg-accent text-on-accent' : 'bg-surface text-muted hover:text-text'}`\nconst smallBtn = 'rounded-lg bg-bg px-3 py-1.5 text-xs transition hover:brightness-125 disabled:opacity-40'\n\nexport default function MarketPage({ me, onProfileChanged }: Props) {\n  const [stars, setStars] = useState(0)\n  const [tab, setTab] = useState<'shop' | 'mine'>('shop')\n  const [kind, setKind] = useState<MarketItem['kind']>('number')\n  const [shop, setShop] = useState<MarketItem[]>([])\n  const [mine, setMine] = useState<MarketItem[]>([])\n  const [sellId, setSellId] = useState<string | null>(null)\n  const [price, setPrice] = useState('')\n  const [busy, setBusy] = useState(false)\n  const [error, setError] = useState<string | null>(null)\n\n  const refresh = useCallback(async () => {\n    try {\n      const [s, sh, mi] = await Promise.all([getStars(), listMarket(), myItems(me.id)])\n      setStars(s); setShop(sh); setMine(mi)\n    } catch (e) { setError(friendly((e as Error).message)) }\n  }, [me.id])\n\n  useEffect(() => { void refresh() }, [refresh])\n\n  async function run(fn: () => Promise<void>) {\n    setBusy(true); setError(null)\n    try { await fn(); await refresh(); onProfileChanged() }\n    catch (e) { setError(friendly((e as Error).message)) }\n    finally { setBusy(false) }\n  }\n\n  const applied = (it: MarketItem) => (it.kind === 'number' ? me.showcase_number : me.showcase_handle) === it.value\n  const shopItems = shop.filter((i) => i.kind === kind)\n  const myList = mine.filter((i) => i.kind === kind)\n\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"flex items-center gap-3 rounded-2xl bg-surface p-4\">\n        <Star size={28} className=\"text-accent\" fill=\"currentColor\" />\n        <div>\n          <div className=\"text-2xl font-semibold\">{stars.toLocaleString('ru-RU')}</div>\n          <div className=\"text-xs text-muted\">Звёзды · пополнение появится позже</div>\n        </div>\n      </div>\n\n      <div className=\"flex gap-2\">\n        <button className={chip(tab === 'shop')} onClick={() => setTab('shop')}>Витрина</button>\n        <button className={chip(tab === 'mine')} onClick={() => setTab('mine')}>Мои</button>\n        <div className=\"flex-1\" />\n        <button className={chip(kind === 'number')} onClick={() => setKind('number')}>Номера</button>\n        <button className={chip(kind === 'username')} onClick={() => setKind('username')}>Юзернеймы</button>\n      </div>\n      {error && <p className=\"text-sm text-pink\">{error}</p>}\n\n      <div className=\"space-y-2\">\n        {tab === 'shop' && shopItems.length === 0 && <p className=\"text-sm text-muted\">Пока ничего не продаётся.</p>}\n        {tab === 'shop' && shopItems.map((it) => (\n          <div key={it.id} className=\"flex items-center gap-3 rounded-xl bg-surface px-4 py-3\">\n            <span className=\"flex-1 font-mono text-sm\">{show(it)}</span>\n            <span className=\"flex items-center gap-1 text-sm\"><Star size={14} className=\"text-accent\" fill=\"currentColor\" />{it.price}</span>\n            {it.owner_id === me.id ? <span className=\"text-xs text-muted\">Ваш лот</span> : (\n              <button className={smallBtn} disabled={busy || stars < (it.price ?? 0)} onClick={() => void run(() => buyItem(it.id))}>Купить</button>\n            )}\n          </div>\n        ))}\n\n        {tab === 'mine' && myList.length === 0 && <p className=\"text-sm text-muted\">Здесь появятся купленные лоты.</p>}\n        {tab === 'mine' && myList.map((it) => (\n          <div key={it.id} className=\"rounded-xl bg-surface px-4 py-3\">\n            <div className=\"flex items-center gap-2\">\n              <span className=\"flex-1 font-mono text-sm\">{show(it)}</span>\n              {applied(it) && <span className=\"text-xs text-accent\">в профиле</span>}\n              {it.price !== null && <span className=\"text-xs text-muted\">продаётся за {it.price}</span>}\n            </div>\n            <div className=\"mt-2 flex flex-wrap gap-2\">\n              {it.price !== null ? (\n                <button className={smallBtn} disabled={busy} onClick={() => void run(() => unlistItem(it.id))}>Снять с продажи</button>\n              ) : (\n                <>\n                  {applied(it)\n                    ? <button className={smallBtn} disabled={busy} onClick={() => void run(() => unapplyItem(it.kind))}>Убрать из профиля</button>\n                    : <button className={smallBtn} disabled={busy} onClick={() => void run(() => applyItem(it.id))}>В профиль</button>}\n                  <button className={smallBtn} onClick={() => { setSellId(sellId === it.id ? null : it.id); setPrice('') }}>Продать</button>\n                </>\n              )}\n            </div>\n            {sellId === it.id && (\n              <div className=\"mt-2 flex gap-2\">\n                <input value={price} inputMode=\"numeric\" placeholder=\"Цена в Звёздах\"\n                  onChange={(e) => setPrice(e.target.value.replace(/\\D/g, '').slice(0, 10))}\n                  className=\"flex-1 rounded-lg bg-bg px-3 py-1.5 text-sm outline-none focus:ring-2 focus:ring-accent\" />\n                <button className={smallBtn} disabled={busy || !price}\n                  onClick={() => void run(async () => { await listItem(it.id, Number(price)); setSellId(null) })}>Выставить</button>\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n      <p className=\"text-xs text-muted\">Номера и юзернеймы — украшения профиля. К регистрации и входу они не относятся.</p>\n    </div>\n  )\n}\n",
 "src/features/settings/SettingsModal.tsx": "import { useRef, useState, type ChangeEvent } from 'react'\nimport { ArrowLeft, Bell, ImagePlus, Lock, LogOut, MessageCircle, Sparkles, Star, Trash2, User, type LucideIcon } from 'lucide-react'\nimport { fileToBackground, type FlagName, type Theme } from '../../lib/prefs'\nimport type { Profile } from '../../lib/types'\nimport Avatar from '../chat/Avatar'\nimport MarketPage from './MarketPage'\n\ntype Page = 'account' | 'notif' | 'privacy' | 'chats' | 'motion' | 'market'\n\nconst TITLES: Record<Page, string> = {\n  account: 'Мой аккаунт', notif: 'Уведомления и звуки', privacy: 'Конфиденциальность',\n  chats: 'Настройки чатов', motion: 'Анимация', market: 'Маркет',\n}\n\ninterface Props {\n  me: Profile\n  email: string\n  theme: Theme\n  background: string | null\n  flags: Record<FlagName, boolean>\n  mutedCount: number\n  onSetTheme: (t: Theme) => void\n  onSetBackground: (value: string | null) => boolean\n  onSetFlag: (name: FlagName, value: boolean) => void\n  onEditProfile: () => void\n  onProfileChanged: () => void\n  onSignOut: () => void\n  onClose: () => void\n}\n\nfunction MenuRow({ Icon, label, value, danger, onClick }: { Icon: LucideIcon; label: string; value?: string; danger?: boolean; onClick: () => void }) {\n  return (\n    <button onClick={onClick} className={`flex w-full items-center gap-4 rounded-xl px-3 py-3 text-left text-sm transition hover:bg-surface ${danger ? 'text-pink' : ''}`}>\n      <Icon size={20} className={danger ? '' : 'text-muted'} />\n      <span className=\"flex-1\">{label}</span>\n      {value && <span className=\"text-accent\">{value}</span>}\n    </button>\n  )\n}\n\nfunction Toggle({ label, hint, checked, onChange }: { label: string; hint?: string; checked: boolean; onChange: (v: boolean) => void }) {\n  return (\n    <button role=\"switch\" aria-checked={checked} onClick={() => onChange(!checked)} className=\"flex w-full items-center gap-3 px-4 py-3 text-left\">\n      <div className=\"flex-1\">\n        <div className=\"text-sm\">{label}</div>\n        {hint && <div className=\"text-xs text-muted\">{hint}</div>}\n      </div>\n      <span className={`h-6 w-11 shrink-0 rounded-full p-0.5 transition ${checked ? 'bg-accent' : 'bg-bg'}`}>\n        <span className={`block h-5 w-5 rounded-full bg-white transition ${checked ? 'translate-x-5' : ''}`} />\n      </span>\n    </button>\n  )\n}\n\nfunction Info({ label, value }: { label: string; value: string }) {\n  return (\n    <div className=\"px-4 py-3\">\n      <div className=\"text-xs text-muted\">{label}</div>\n      <div className=\"text-sm break-words\">{value}</div>\n    </div>\n  )\n}\n\nexport default function SettingsModal(p: Props) {\n  const [page, setPage] = useState<Page | null>(null)\n  const [error, setError] = useState<string | null>(null)\n  const fileRef = useRef<HTMLInputElement>(null)\n\n  async function onFile(e: ChangeEvent<HTMLInputElement>) {\n    const file = e.target.files?.[0]\n    e.target.value = ''\n    if (!file) return\n    try {\n      const ok = p.onSetBackground(await fileToBackground(file))\n      setError(ok ? null : 'Не удалось сохранить: в браузере мало места.')\n    } catch (err) { setError((err as Error).message) }\n  }\n\n  const seg = (t: Theme) =>\n    `flex-1 rounded-lg py-2 text-sm transition ${p.theme === t ? 'bg-accent text-on-accent' : 'text-muted hover:text-text'}`\n\n  return (\n    <div className=\"fixed inset-0 z-30 flex items-center justify-center bg-black/60 p-4\" onClick={p.onClose}>\n      <div className=\"max-h-[85vh] w-full max-w-md overflow-y-auto rounded-3xl bg-bg2 p-4\" onClick={(e) => e.stopPropagation()}>\n        <div className=\"mb-3 flex items-center gap-2 px-2\">\n          {page && <button onClick={() => { setPage(null); setError(null) }} className=\"rounded-lg p-1 text-muted hover:text-text\"><ArrowLeft size={20} /></button>}\n          <h2 className=\"text-lg font-medium\">{page ? TITLES[page] : 'Настройки'}</h2>\n        </div>\n\n        {page === null && (\n          <div>\n            <MenuRow Icon={User} label=\"Мой аккаунт\" onClick={() => setPage('account')} />\n            <MenuRow Icon={Bell} label=\"Уведомления и звуки\" onClick={() => setPage('notif')} />\n            <MenuRow Icon={Lock} label=\"Конфиденциальность\" onClick={() => setPage('privacy')} />\n            <MenuRow Icon={MessageCircle} label=\"Настройки чатов\" onClick={() => setPage('chats')} />\n            <MenuRow Icon={Sparkles} label=\"Анимация\" onClick={() => setPage('motion')} />\n            <MenuRow Icon={Star} label=\"Маркет\" value=\"Звёзды\" onClick={() => setPage('market')} />\n            <div className=\"my-2 border-t border-line\" />\n            <MenuRow Icon={LogOut} label=\"Выйти из аккаунта\" danger onClick={p.onSignOut} />\n          </div>\n        )}\n\n        {page === 'account' && (\n          <div className=\"space-y-4\">\n            <div className=\"flex items-center gap-4 px-2\">\n              <Avatar name={p.me.display_name} url={p.me.avatar_url} size={64} />\n              <div className=\"min-w-0\">\n                <div className=\"truncate font-medium\">{p.me.display_name}</div>\n                <div className=\"text-sm text-muted\">@{p.me.username}</div>\n              </div>\n            </div>\n            <div className=\"divide-y divide-line rounded-xl bg-surface\">\n              <Info label=\"Почта\" value={p.email || '—'} />\n              <Info label=\"О себе\" value={p.me.bio || 'Не указано'} />\n              {p.me.showcase_number && <Info label=\"Номер\" value={p.me.showcase_number} />}\n              {p.me.showcase_handle && <Info label=\"Коллекционный юзернейм\" value={`@${p.me.showcase_handle}`} />}\n            </div>\n            <button onClick={() => { p.onClose(); p.onEditProfile() }}\n              className=\"w-full rounded-xl bg-accent py-2.5 text-sm font-semibold text-on-accent transition hover:brightness-110\">\n              Редактировать профиль\n            </button>\n          </div>\n        )}\n\n        {page === 'notif' && (\n          <div className=\"divide-y divide-line rounded-xl bg-surface\">\n            <Toggle label=\"Звук новых сообщений\" hint=\"Сигнал, когда пишут в закрытый чат\" checked={p.flags.sound} onChange={(v) => p.onSetFlag('sound', v)} />\n            <Info label=\"Чатов без звука\" value={`${p.mutedCount} (настраивается в профиле собеседника)`} />\n          </div>\n        )}\n\n        {page === 'privacy' && (\n          <div className=\"divide-y divide-line rounded-xl bg-surface\">\n            <Toggle label=\"Показывать, что я в сети\" hint=\"Если выключить, другие увидят вас «не в сети»\" checked={p.flags.online} onChange={(v) => p.onSetFlag('online', v)} />\n          </div>\n        )}\n\n        {page === 'motion' && (\n          <div className=\"divide-y divide-line rounded-xl bg-surface\">\n            <Toggle label=\"Анимации интерфейса\" hint=\"Выключите, чтобы убрать переходы и пульсации\" checked={p.flags.motion} onChange={(v) => p.onSetFlag('motion', v)} />\n          </div>\n        )}\n\n        {page === 'chats' && (\n          <div className=\"space-y-5\">\n            <div>\n              <div className=\"mb-2 px-1 text-xs text-muted\">Тема</div>\n              <div className=\"flex gap-1 rounded-xl bg-surface p-1\">\n                <button className={seg('dark')} onClick={() => p.onSetTheme('dark')}>Тёмная</button>\n                <button className={seg('light')} onClick={() => p.onSetTheme('light')}>Светлая</button>\n              </div>\n            </div>\n            <div>\n              <div className=\"mb-2 px-1 text-xs text-muted\">Фон чата</div>\n              <div className=\"mb-2 h-24 rounded-xl bg-surface bg-cover bg-center\"\n                style={p.background ? { backgroundImage: `url(${p.background})` } : undefined} />\n              <input ref={fileRef} type=\"file\" accept=\"image/*\" className=\"hidden\" onChange={(e) => void onFile(e)} />\n              <div className=\"flex gap-2\">\n                <button onClick={() => fileRef.current?.click()}\n                  className=\"flex flex-1 items-center justify-center gap-2 rounded-xl bg-surface py-2 text-sm transition hover:brightness-110\">\n                  <ImagePlus size={16} /> Загрузить\n                </button>\n                {p.background && (\n                  <button onClick={() => { p.onSetBackground(null); setError(null) }}\n                    className=\"flex items-center gap-2 rounded-xl bg-surface px-3 py-2 text-sm text-muted transition hover:text-text\">\n                    <Trash2 size={16} /> Убрать\n                  </button>\n                )}\n              </div>\n              <p className=\"mt-2 text-xs text-muted\">Фон хранится только на этом устройстве.</p>\n              {error && <p className=\"mt-1 text-xs text-pink\">{error}</p>}\n            </div>\n          </div>\n        )}\n\n        {page === 'market' && <MarketPage me={p.me} onProfileChanged={p.onProfileChanged} />}\n      </div>\n    </div>\n  )\n}\n",
 "src/App.tsx": "import { useCallback, useEffect, useState } from 'react'\nimport { supabase } from './lib/supabase'\nimport type { Profile } from './lib/types'\nimport {\n  getFlag, getMuted, loadBackground, loadTheme, saveBackground, saveTheme, setFlag,\n  setMuted as persistMuted, type FlagName, type Theme,\n} from './lib/prefs'\nimport { useSession } from './features/auth/session'\nimport AuthPage from './features/auth/AuthPage'\nimport NavRail from './features/chat/NavRail'\nimport Sidebar from './features/chat/Sidebar'\nimport ChatView from './features/chat/ChatView'\nimport RightPanel from './features/chat/RightPanel'\nimport ProfileModal from './features/profile/ProfileModal'\nimport SettingsModal from './features/settings/SettingsModal'\nimport { useChats, useOnline } from './features/chat/hooks'\n\nconst PROFILE_SELECT = 'id, username, display_name, bio, avatar_url, created_at, showcase_number, showcase_handle'\n\nfunction Messenger({ userId }: { userId: string }) {\n  const { session } = useSession()\n  const [me, setMe] = useState<Profile | null>(null)\n  const [error, setError] = useState<string | null>(null)\n  const [selectedId, setSelectedId] = useState<string | null>(null)\n  const [showInfo, setShowInfo] = useState(false)\n  const [profileOpen, setProfileOpen] = useState(false)\n  const [settingsOpen, setSettingsOpen] = useState(false)\n  const [theme, setTheme] = useState<Theme>(loadTheme)\n  const [background, setBackground] = useState<string | null>(loadBackground)\n  const [muted, setMutedState] = useState<string[]>(getMuted)\n  const [flags, setFlags] = useState<Record<FlagName, boolean>>({\n    sound: getFlag('sound'), online: getFlag('online'), motion: getFlag('motion'),\n  })\n  const { chats, loading, unread, last, reload } = useChats(userId, selectedId)\n  const online = useOnline(userId, flags.online)\n\n  const loadMe = useCallback(() => {\n    supabase.from('profiles').select(PROFILE_SELECT).eq('id', userId).single()\n      .then(({ data, error }) => (error ? setError(error.message) : setMe(data as Profile)))\n  }, [userId])\n  useEffect(() => { loadMe() }, [loadMe])\n\n  if (error) return <p className=\"p-6 text-pink\">Ошибка чтения профиля: {error}</p>\n  if (!me) return <div className=\"flex h-full items-center justify-center text-muted\">Загрузка…</div>\n\n  const selected = chats.find((c) => c.id === selectedId) ?? null\n  const totalUnread = Object.values(unread).reduce((a, b) => a + b, 0)\n\n  function changeTheme(next: Theme) { saveTheme(next); setTheme(next) }\n  function changeBackground(value: string | null): boolean {\n    const ok = saveBackground(value)\n    if (ok) setBackground(value)\n    return ok\n  }\n  function changeFlag(name: FlagName, value: boolean) {\n    setFlag(name, value)\n    setFlags((f) => ({ ...f, [name]: value }))\n  }\n  function toggleMute(chatId: string) {\n    const next = muted.includes(chatId) ? muted.filter((id) => id !== chatId) : [...muted, chatId]\n    persistMuted(next)\n    setMutedState(next)\n  }\n\n  return (\n    <div className=\"flex h-full\">\n      <div className={selected ? 'hidden md:flex' : 'flex w-full md:w-auto'}>\n        <NavRail me={me} theme={theme} totalUnread={totalUnread}\n          onToggleTheme={() => changeTheme(theme === 'dark' ? 'light' : 'dark')}\n          onOpenProfile={() => setProfileOpen(true)} onOpenSettings={() => setSettingsOpen(true)} />\n        <Sidebar myId={me.id} chats={chats} loading={loading} selectedId={selectedId} unread={unread}\n          last={last} online={online} muted={muted} onSelect={setSelectedId} onChatCreated={reload} />\n      </div>\n      {selected ? (\n        <>\n          <ChatView key={selected.id} chat={selected} chats={chats} myId={me.id} myName={me.display_name}\n            background={background} online={selected.otherId !== null && online.has(selected.otherId)}\n            onBack={() => setSelectedId(null)} onToggleInfo={() => setShowInfo((v) => !v)} />\n          {showInfo && selected.kind !== 'saved' && (\n            <RightPanel chat={selected} muted={muted.includes(selected.id)}\n              online={selected.otherId !== null && online.has(selected.otherId)}\n              onToggleMute={() => toggleMute(selected.id)} onClose={() => setShowInfo(false)} />\n          )}\n        </>\n      ) : (\n        <div className=\"hidden flex-1 items-center justify-center bg-bg text-sm text-muted md:flex\">Выбери чат или найди человека</div>\n      )}\n      {profileOpen && <ProfileModal me={me} onClose={() => setProfileOpen(false)}\n        onSaved={(p) => { setMe(p); setProfileOpen(false) }} />}\n      {settingsOpen && <SettingsModal me={me} email={session?.user.email ?? ''} theme={theme} background={background}\n        flags={flags} mutedCount={muted.length} onSetTheme={changeTheme} onSetBackground={changeBackground}\n        onSetFlag={changeFlag} onEditProfile={() => setProfileOpen(true)} onProfileChanged={loadMe}\n        onSignOut={() => void supabase.auth.signOut()} onClose={() => setSettingsOpen(false)} />}\n    </div>\n  )\n}\n\nexport default function App() {\n  const { session, loading } = useSession()\n  if (loading) return <div className=\"flex h-full items-center justify-center text-muted\">Загрузка…</div>\n  return session ? <Messenger userId={session.user.id} /> : <AuthPage />\n}\n"
}
for (const [path, content] of Object.entries(files)) {
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, content, 'utf8')
  console.log('создан', path)
}
console.log('\nГотово! Сначала выполни SQL из supabase/migrations/0004_slice5.sql в Supabase.')
